insert into species_def values ('bevere', 'Bevere', 'A broad, flat-tailed gnawer with orange teeth and oiled fur. It never strays far from water, and it fells a tree faster than a man with a hatchet.', 26, 3, 1.8, 1, 0.1, 'a vegetable or something starchy', true, 'woodcut', 8, 'takes the {food} in both paws, eats it without hurry, and slips back into the water', 'slaps its tail and slides into the water', 4, true, false, false, false, false, false, false, false, false, false, false, false, null, null, 'passive', null, null, null, null);
