insert into species_def values ('crawler', 'Crawler', 'A broad sand-coloured crab that goes at everything sideways. It shovels sand with its claws faster than a man with a spade, and it has never once been sorry for pinching anybody.', 24, 5, 1.6, 1, 0.1, 'a vegetable', false, 'sand', 8, 'takes the {food} in one claw, waves the other at you, and backs off sideways', 'scuttles off sideways and buries itself in the sand', 4, false, false, false, true, false, false, false, false, false, false, true, false, null, 0.12, 'defensive', null, 'cut', null, null);
