insert into species_def values ('noot', 'Noot', 'A plump, upright waddler in a slate coat, with a broad bill it uses as a spade and a flat tail it uses as a stool. It spends its whole day up to the knees in a clay pit and appears to think this is the good life.', 26, 3, 1.5, 1, 0.12, 'a root vegetable', true, 'clay', 9, 'takes the {food} in its bill, honks once through it, and waddles off', 'waddles back to the nearest clay pit and settles into it', 4, false, false, false, false, true, false, false, false, false, false, false, false, null, null, null, null, 'pierce', null, null);
insert into species_diet values ('noot', 'carrot');
insert into species_diet values ('noot', 'onion');
insert into species_diet values ('noot', 'potato');
insert into species_diet values ('noot', 'mixed_grass');
insert into species_def values ('embra', 'Embra', 'A soot-dark, slow-blinking creature that sleeps in the peat and tar of the marshes and wakes up wherever there is a fire. It carries wood the way other creatures carry food, and it will not eat anything raw.', 24, 4, 1.5, 1, 0.1, 'something cooked', true, 'stoke', 10, 'sniffs at the {food}, finds it cold, and turns its back on you', 'settles into the warm ash and pays you no more attention', 4, false, false, false, false, false, true, false, false, false, false, false, false, null, null, null, null, 'burn', null, null);
