insert into species_def values ('seavic', 'Seavic', 'A quick red-brown squirrel with a tail it wears like a cloak and cheeks it stuffs with seed. It lives in the treetops and cannot leave a field alone.', 14, 2, 2.6, 1, 0.12, 'an acorn or a handful of nuts', true, 'farm', 8, 'stuffs the {food} into its cheeks and is up the nearest trunk before you can blink', 'flicks its tail and runs up the nearest tree', 4, false, true, false, false, false, false, false, false, false, false, false, false, null, null, 'passive', null, null, null, null);
