insert into species_def values ('rowl', 'Rowl', 'A deep-chested hunter that runs the treeline in the half-light. It hunts the moment it sees you, and tamed it will hunt for you instead: give it a settlement and it works a circuit of it, and the more it fights the wider that circuit gets.', 46, 14, 2.5, 35, 0.05, 'meat', false, 'hunt', 12, 'takes the {food} and keeps its shoulder to you the whole while, unconvinced', 'goes off at a long easy lope and is lost in the trees', 4, false, true, false, false, false, false, false, true, false, false, true, false, null, 0.08, 'aggressive', null, 'cut', null, null);
