insert into species_def values ('tinka', 'Tinka', 'A small, fussy thing with far too many fingers, forever taking something apart to see how it is put together. Left alone with your gear it mends it, which is more than most would do.', 16, 2, 2, 25, 0.08, 'nuts or something sweet', true, 'mend', 6, 'turns the {food} over twice looking for a seam in it, then puts it down', 'pockets something of yours and is gone before you can see which', 4, false, false, false, false, false, false, false, false, false, false, false, false, null, null, null, null, null, null, null);
