insert into species_def values ('gorral', 'Gorral', 'A horned cliff-goat that stands on ground you would not put a ladder against. Under a saddle it goes up what an Orse turns away from, and the more it is worked the worse the ground it will take.', 44, 7, 2.4, 40, 0.06, 'grass or a root', false, null, 6, 'takes the {food} off the flat of your hand and is four lengths up the rock before you blink', 'goes up the face in three bounds and looks down at you from the top', 4, false, false, false, false, false, false, true, false, false, false, true, false, null, null, null, null, 'crush', null, null);
