insert into species_def values ('shaggan', 'Shaggan', 'A mountain of hair on four legs, slower than anything else that pulls and stronger than all of them. One in the traces is a waste of a Shaggan; four of them will move a loaded wagon as though it were empty.', 90, 12, 1, 35, 0.06, 'grass or grain', false, null, 6, 'eats the {food}, and the grass around it, and stands there', 'turns and walks into the wind, which is where it was going anyway', 4, false, false, false, false, false, false, false, false, false, false, true, false, null, null, null, null, 'crush', null, null);
