insert into cast_def values ('call', 'Call', 12, 3, 'self', 'Whatever travels with you is beside you again, from wherever it had got to.');
insert into cast_def values ('mend', 'Mend', 18, 8, 'item', 'Every mark of use comes off one thing at once, as though it were off the bench this morning.');
insert into cast_def values ('dawnlight', 'Light of the dawn', 26, 16, 'self', 'Everything open on you closes, and anything that had gone bad is clean.');
insert into cast_def values ('cunning', 'Circle of cunning', 34, 24, 'item', 'A tool comes out of it working better than it was ever made to, and stays that way. Three times is as far as anything will take it.');
insert into cast_def values ('fairwind', 'Fair wind', 30, 30, 'self', 'The wind comes round behind wherever you are pointed and holds there for a while.');
insert into cast_def values ('bounty', 'Bounty', 44, 40, 'self', 'Every field on the settlement comes on a stage, all at once, in front of you.');
insert into bridge_def values ('rope', 'Rope bridge', 14, 'mallet', 'carpentry', 18, false, 'Two hawsers and a plank walkway. It goes a long way for very little and it sways the whole time; nothing with a wheel on it is crossing.');
