insert into bridge_bill values ('wood', 'nail', 12);
insert into bridge_def values ('stone', 'Stone arch', 8, 'trowel', 'masonry', 44, true, 'Voussoirs turned over a centring and a slab road laid on the fill. It is the work of a season and it will outlast everybody who used it.');
