insert into path_def values ('love', 'Love', 'The gardener’s way. Things grow for you, things trust you, and what is hurt mends.');
insert into path_step values ('love', 1, 3, 'Green thumb', 'Everything sown on your settlement comes on a fifth faster.', null, null, null);
insert into path_step values ('love', 2, 12, 'Refresh', 'Hunger and thirst, both full, in a breath.', 'refresh', 1200, 'You are neither hungry nor thirsty.');
insert into path_step values ('love', 3, 25, 'Gentle hand', 'A wild thing is a quarter readier to trust you.', null, null, null);
insert into path_step values ('love', 4, 45, 'Mend the flesh', 'Everything open on you closes and a good deal of the damage goes with it.', 'mendflesh', 2400, 'Wounds closed.');
insert into path_step values ('love', 5, 70, 'Abundance', 'A harvest gives a third more than it did.', null, null, null);
insert into path_def values ('knowledge', 'Knowledge', 'The reader’s way. The work goes in faster, you see further, and you can read what is in front of you.');
insert into path_step values ('knowledge', 1, 3, 'Attentive', 'Everything you do teaches you a tenth faster, for good.', null, null, null);
insert into path_step values ('knowledge', 2, 12, 'Sense the rock', 'What metal is under the ground within fifteen tiles, all at once.', 'sense', 900, 'The ground gives up what is in it.');
insert into path_step values ('knowledge', 3, 25, 'Reader', 'You read the blood of any wildermon at a glance, whatever your husbandry.', null, null, null);
insert into path_step values ('knowledge', 4, 45, 'Recall the way', 'You are standing at your own token, however far off you had got.', 'recall', 2400, 'Home.');
insert into path_step values ('knowledge', 5, 70, 'Keen sight', 'You see a quarter further than anybody else on the island.', null, null, null);
insert into path_def values ('power', 'Power', 'The plain way. You carry more, you hit harder, and less of what is aimed at you lands.');
insert into path_step values ('power', 1, 3, 'Strong back', 'You carry a fifth more than your body says you should.', null, null, null);
insert into path_step values ('power', 2, 12, 'Second wind', 'Your wind comes back all at once.', 'secondwind', 720, 'Wind back.');
insert into path_step values ('power', 3, 25, 'Hard hands', 'You hit a sixth harder with anything, or with nothing.', null, null, null);
insert into path_step values ('power', 4, 45, 'Fury', 'For half a minute everything you hit takes twice what it would.', 'fury', 2400, 'Fury.');
insert into path_step values ('power', 5, 70, 'Ironhide', 'What you are wearing turns a tenth more of every blow.', null, null, null);
