update item_def set description = 'Pale metal that holds a light of its own. Twenty kilograms of ore give a tenth of this.' where id = 'glimmersteel_lump';
update item_def set description = 'The rarest metal in the rock, and the hardest won.' where id = 'seryll_lump';
update item_def set description = 'A sand mould. It wears a little every time it is filled, and no mould can be mended.' where id = 'anvil_mould';
update item_def set description = 'A gang mould with a hundred little channels in it. One lump of metal runs out as a hundred nails. It wears like any mould and cannot be mended.' where id = 'nail_mould';
update item_def set description = 'A sand mould. It wears a little every time it is filled, and no mould can be mended.' where id = 'pan_mould';
update item_def set description = 'A sand mould. It wears a little every time it is filled, and no mould can be mended.' where id = 'rake_head_mould';
update item_def set description = 'A sand mould. It wears a little every time it is filled, and no mould can be mended.' where id = 'shovel_head_mould';
update item_def set description = 'A sand mould. It wears a little every time it is filled, and no mould can be mended.' where id = 'hatchet_head_mould';
update item_def set description = 'A sand mould. It wears a little every time it is filled, and no mould can be mended.' where id = 'sickle_blade_mould';
update item_def set description = 'A sand mould. It wears a little every time it is filled, and no mould can be mended.' where id = 'pickaxe_head_mould';
update item_def set description = 'A sand mould. It wears a little every time it is filled, and no mould can be mended.' where id = 'knife_blade_mould';
update item_def set description = 'A sand mould. It wears a little every time it is filled, and no mould can be mended.' where id = 'sword_blade_mould';
update item_def set description = 'A sand mould. It wears a little every time it is filled, and no mould can be mended.' where id = 'helm_mould';
update item_def set description = 'A long sand mould for a wagon axle. It wears a little every time it is filled, and no mould can be mended.' where id = 'axle_mould';
update item_def set description = 'A gang mould that runs one lump out as four metal ribbons. It wears like any mould and cannot be mended.' where id = 'ribbon_mould';
update item_def set description = 'Ten grams of metal apiece. Nothing is nailed together without them.' where id = 'nail';
update item_def set description = 'Shaft, head and feather. A bow spends one with every shot.' where id = 'arrow';
update item_def set description = 'Three to an arrow, and only a bird carries them.' where id = 'feather';
update item_def set description = 'Spun on a spindle. Woven on a loom it becomes cloth.' where id = 'yarn';
update item_def set description = 'Cut off a rose bush with a sickle. Boiled, they give a pink that nothing else on the island gives.' where id = 'rose_petals';
update item_def set description = 'Cut off a lavender bush with a sickle. Boiled, it gives a violet.' where id = 'lavender';
update item_def set description = 'A fleece shorn from a living Woola. It grows back, which fur never does.' where id = 'wool';
update item_def set description = 'Wool or cotton spun and woven. Stuffs a mattress and makes what you wear.' where id = 'cloth';
update item_def set description = 'A soft pelt taken from a butchered wildermon.' where id = 'fur';
update item_def set description = 'A raw skin off a carcass. Useless until it has been through lye.' where id = 'hide';
update item_def set description = 'Hide tanned in lye and worked soft. What every leather thing is cut from.' where id = 'leather';
update item_def set description = 'A small scent gland. Rare, and prized by alchemists.' where id = 'gland';
update item_def set description = 'A straight length of wood, carved from a log. Handles for tools and rails for fences.' where id = 'shaft';
update item_def set description = 'Flat bands of metal, beaten out four to a lump. Everything that has to hold together under a load is banded with them.' where id = 'ribbon';
update item_def set description = 'A cast axle as long as a cart is wide. Two wheels turn on one.' where id = 'big_axle';
update item_def set description = 'Spokes, felloes and a metal tyre shrunk on hot. A cart takes two and a wagon four.' where id = 'large_wheel';
update item_def set description = 'A shaped bar and a leather harness. A wildermon is hitched into one to pull.' where id = 'yoke';
update item_def set drink = 0.3 where id = 'milk_bucket';
update item_def set description = 'Five litres of milk, still warm. Drink it, or work it into cheese while it is fresh.' where id = 'milk_bucket';
update item_def set food = 0.3 where id = 'cheese';
update item_def set description = 'Milk pressed and left to itself for a while. It keeps far better than what it was made of.' where id = 'cheese';
update item_def set food = 0.22 where id = 'honey';
update item_def set description = 'Comb honey out of a hive. It keeps almost forever and everything on the island wants it.' where id = 'honey';
update item_def set description = 'Comb rendered down. It is what a candle is, and what a waxed thread is drawn through.' where id = 'wax';
update item_def set description = 'Four ribbons of iron, two panes of oiled cloth and a handle. Put a candle in it, strike it, and the night stops being a wall.' where id = 'lantern';
update item_def set description = 'A shaft with oiled cloth wound round the head of it. Touch it to a fire and it burns for a few minutes and throws a small circle — long enough to get somewhere, not long enough to work by.' where id = 'torch';
update item_def set description = 'Wax drawn round a wick. Set one in a lantern and it will show you the ground on the blackest night.' where id = 'candle';
update item_def set description = 'What a Middun leaves behind, which is the best thing that ever happened to a field. Spread it on tilled ground.' where id = 'compost';
update item_def set description = 'A tree of wood under stitched leather, girthed and stirruped. Fit one to an Orse and you can ride it.' where id = 'saddle';
update item_def set description = 'Headstall, bit and reins. Without one there is nothing to steer by.' where id = 'bridle';
update item_def set description = 'Plant it on grass or dirt to grow a tree. Wilts quickly if left lying around.' where id = 'sprout';
update item_def set food = 0.08 where id = 'blueberry';
update item_def set food = 0.08 where id = 'raspberry';
