update item_def set food = 0.05 where id = 'nuts';
update item_def set food = 0.18 where id = 'meat';
update item_def set description = 'Raw meat from a butchered wildermon. Cook it at a campfire and it feeds you twice over.' where id = 'meat';
update item_def set food = 0.35 where id = 'cooked_meat';
update item_def set food = 0.22 where id = 'baked_potato';
update item_def set food = 0.16 where id = 'roast_onion';
update item_def set food = 0.12 where id = 'roast_nuts';
update item_def set food = 0.3 where id = 'berry_compote';
update item_def set description = 'Berries stewed down in a bowl over a fire.' where id = 'berry_compote';
update item_def set food = 0.75 where id = 'stew';
update item_def set description = 'Meat and vegetables simmered together. The best meal a campfire can make.' where id = 'stew';
update item_def set food = 0.6 where id = 'pottage';
update item_def set description = 'A thick pot of vegetables and grain, simmered down slowly.' where id = 'pottage';
update item_def set food = 0.42 where id = 'bread';
update item_def set description = 'A baked loaf. The first food that keeps and travels.' where id = 'bread';
update item_def set food = 0.32 where id = 'porridge';
update item_def set description = 'Cornmeal boiled thick in a bowl.' where id = 'porridge';
update item_def set food = 0.28 where id = 'preserves';
update item_def set description = 'Berries put up in a sealed jar. They keep for a very long time.' where id = 'preserves';
update item_def set description = 'Wheat ground between two stones. Wet it and it becomes dough.' where id = 'flour';
update item_def set description = 'Corn ground coarse. Boiled up it makes porridge.' where id = 'cornmeal';
update item_def set description = 'Flour and water worked together. It wants a fire under it.' where id = 'dough';
update item_def set description = 'A strip of cloth for binding a wound. One strip, one wound.' where id = 'bandage';
update item_def set description = 'Cut from a reed bed. Soaked and pressed it becomes papyrus.' where id = 'reed';
update item_def set description = 'A pressed sheet, smooth enough to take ink.' where id = 'papyrus';
update item_def set description = 'Soot, gland and lye water, ground together until it flows black.' where id = 'ink';
update item_def set description = 'Papyrus sewn between leather boards. Reading it sharpens the head, and wears the pages.' where id = 'book';
update item_def set description = 'A broken piece of something old. Find the rest of it and a restorer can put it back together.' where id = 'fragment';
update item_def set description = 'A square of oiled hide with a stretch of country drawn on it and no names anywhere. Read it to see the picture; walk until the ground matches, then dig. Something is always left to watch over a hoard. Keep it in a pack or a crate — left lying in a field it will rot, and take the hoard with it.' where id = 'treasure_map';
update item_def set description = 'A small figure in worn stone, carried by people who are long gone.' where id = 'statuette';
update item_def set description = 'A closed clay lamp with a wick hole. It still smells faintly of oil.' where id = 'old_lamp';
update item_def set description = 'A disc of bronze polished on one face. It gives back a dim, honest likeness.' where id = 'bronze_mirror';
update item_def set description = 'Fine teeth cut in old bone. Somebody took a great deal of trouble over it.' where id = 'bone_comb';
update item_def set food = 0.01 where id = 'sage';
update item_def set food = 0.01 where id = 'basil';
update item_def set food = 0.01 where id = 'thyme';
update item_def set food = 0.01 where id = 'mint';
update item_def set food = 0.01 where id = 'rosemary';
