update item_def set food = 0.05 where id = 'wheat';
update item_def set food = 0.11 where id = 'corn';
update item_def set description = 'A belt of loops and pouches. Wear it and it carries the jobs you do most, ready to hand: one loop for every ten points of how well it was made.' where id = 'toolbelt';
update item_def set description = 'Woven wide enough to sit on cross-legged. Lay it down somewhere quiet and think about nothing.' where id = 'rug';
update item_def set description = 'Tusk laid along the belly, sinew glued along the back, both off something that was trying to kill you. It throws an arrow seventeen tiles.' where id = 'composite_bow';
update item_def set description = 'Dragon scale riveted to a leather cap.' where id = 'scale_helm';
update item_def set description = 'Dragon scale laid in courses over a leather body. It turns more than plate and weighs less than chain.' where id = 'scale_cuirass';
update item_def set description = 'Dragon scale on the outside of the arm.' where id = 'scale_sleeves';
update item_def set description = 'Dragon scale down the thigh and shin.' where id = 'scale_leggings';
update item_def set description = 'Dragon scale over the instep.' where id = 'scale_boots';
update item_def set description = 'Cut from the jaw of something that meant to use it on you. Hard, close-grained and springy: the belly of a composite bow is made of it.' where id = 'tusk';
update item_def set description = 'Dried back-strap. It pulls like nothing that grows and it is what the back of a composite bow is laid with.' where id = 'sinew';
update item_def set description = 'A plate the size of your hand, warm to hold and lighter than it looks. Nothing on this island turns a blow like it, and there is only one place to get one.' where id = 'dragon_scale';
update item_def set description = 'Turned out of damp dirt with a shovel. The first bait anybody uses, and the one that never stops working on small fish.' where id = 'worm';
update item_def set description = 'Yarn knotted to a rope headline. Dragged through shallow water it takes a great many small fish at once and lets the big ones through.' where id = 'fishing_net';
update item_def set description = 'A woven basket trap with a throat it is easy to swim into and hard to swim out of. Set it in water, bait it, and leave it.' where id = 'creel';
update item_def set description = 'A noose of rope on a bent shaft. Set it out in the country, bait it, and come back to whatever came to the bait.' where id = 'snare';
update item_def set description = 'A weighted board on a trigger. It holds very nearly anything that walks, and it is a great deal of work to build.' where id = 'deadfall';
update item_def set description = 'Herbs worked into cotton. Laid on the wound it suits, it stops the bleeding, keeps the dirt out and closes it twice as fast as cloth.' where id = 'cover';
update item_def set description = 'A pot of colour, struck with lye so it bites and holds. One pot does one thing.' where id = 'dye';
update item_def set description = 'Cloth on a staff. Plant it on the deed and fly your colour over it.' where id = 'banner';
update item_def set description = 'Wemp laid up into three strands on a rope tool. Everything that has to hold, hold fast or haul is roped.' where id = 'rope';
update item_def set description = 'Three ropes laid up again into a hawser. It moors a hull, hangs a bucket down a shaft and carries a span of bridge.' where id = 'thick_rope';
update item_def set food = 0.06 where id = 'onion';
update item_def set description = 'Something dead. Butcher it before it rots: meat, fur, leather, bone and glands off a wildermon, and off one of the bad things, tusk, sinew and worse.' where id = 'corpse';
update item_def set description = 'Three legs and a seat. Set it down anywhere.' where id = 'stool';
update item_def set description = 'A board across two posts, made to be written on. Set it up and give it a name, and the name stands there for anyone walking past.' where id = 'sign';
update item_def set description = 'A board wide enough to write a sentence on. Set it up where a road forks and nobody need guess again.' where id = 'great_sign';
update item_def set description = 'A chair with a proper back to it. Set it down anywhere.' where id = 'chair';
update item_def set description = 'Seats two at a pinch, three in a good mood.' where id = 'bench';
update item_def set description = 'A square table on four legs.' where id = 'table';
update item_def set description = 'The table a hall is built around.' where id = 'long_table';
update item_def set description = 'A desk with drawers under the top. Holds 20 things.' where id = 'desk';
update item_def set description = 'A bed with a stuffed mattress on it.' where id = 'bed';
update item_def set description = 'A narrow bed for a narrow room.' where id = 'cot';
update item_def set description = 'A banded chest. Holds 60 things.' where id = 'chest';
update item_def set description = 'A small strongbox. Holds 25 things.' where id = 'coffer';
update item_def set description = 'A cupboard with doors on it. Holds 80 things.' where id = 'cupboard';
update item_def set description = 'Tall enough to hang a cloak full length. Holds 100 things.' where id = 'wardrobe';
update item_def set description = 'A long open rack of shelves. Holds 120 things.' where id = 'shelves';
update item_def set description = 'Shelves with a back and a cornice. Holds 90 things.' where id = 'bookshelf';
update item_def set description = 'A deep cool cupboard for a kitchen. The largest storage there is: 150 things.' where id = 'larder';
update item_def set description = 'A decked rack two spots across and four deep. It holds nothing itself: eight plank crates stand on it, each its own crate, and you can see across a warehouse how many are full.' where id = 'crate_shelf';
update item_def set description = 'Staves and hoops. Holds 80 litres of one liquid, and nothing solid.' where id = 'barrel';
update item_def set description = 'A slanted stand to read from.' where id = 'lectern';
update item_def set description = 'Pegs on a post, by the door.' where id = 'coat_rack';
update item_def set description = 'A box of earth with something green in it.' where id = 'planter';
update item_def set description = 'Keeps the wood off the wet ground. Holds 40 things.' where id = 'firewood_rack';
update item_def set drink = 0.4 where id = 'ale_bucket';
update item_def set description = 'Thin, sour and honest. Drink it and the work goes easier for a good while.' where id = 'ale_bucket';
update item_def set drink = 0.45 where id = 'cider_bucket';
update item_def set description = 'Pressed apples gone dangerous. A trade comes easier after it.' where id = 'cider_bucket';
update item_def set drink = 0.5 where id = 'mead_bucket';
update item_def set description = 'Honey and time. The best thing to come out of a hive after the honey itself.' where id = 'mead_bucket';
update item_def set drink = 0.5 where id = 'wine_bucket';
update item_def set description = 'Cherries, water and three quarters of an hour of patience.' where id = 'wine_bucket';
update item_def set description = 'Two shafts spliced, a waxed line and a strip of metal bent into a hook. Stand at water and fish.' where id = 'fishing_rod';
update item_def set food = 0.06 where id = 'minnow';
update item_def set description = 'A finger of silver. Bait, if you are honest about it.' where id = 'minnow';
update item_def set food = 0.2 where id = 'perch';
update item_def set description = 'Striped and spiny and everywhere there is water with a foot of depth.' where id = 'perch';
update item_def set food = 0.34 where id = 'trout';
update item_def set description = 'Runs where the water is properly deep. Worth cooking properly.' where id = 'trout';
update item_def set food = 0.55 where id = 'pike';
update item_def set description = 'All teeth and bad temper. It takes a good hand to land one.' where id = 'pike';
update item_def set food = 0.85 where id = 'sturgeon';
update item_def set description = 'The deep water fish. Most people fish for a lifetime and never see one.' where id = 'sturgeon';
update item_def set food = 0.52 where id = 'cooked_fish';
update item_def set description = 'Fish over a fire, which is what fish is for.' where id = 'cooked_fish';
update item_def set food = 0.16 where id = 'apple';
update item_def set description = 'Picked off the tree. Keeps a while, bakes into a pie, and presses into cider.' where id = 'apple';
update item_def set food = 0.07 where id = 'cherry';
update item_def set description = 'Sweet and gone in a moment. Better preserved than eaten by the handful.' where id = 'cherry';
update item_def set food = 0.09 where id = 'olive';
update item_def set description = 'Bitter off the branch and worth a great deal pressed.' where id = 'olive';
update item_def set food = 0.3 where id = 'olive_oil';
update item_def set description = 'Pressed from olives under a quern. Keeps almost indefinitely and makes anything cooked in it better.' where id = 'olive_oil';
update item_def set food = 0.62 where id = 'apple_pie';
update item_def set description = 'Pastry over stewed apple, baked in an oven. As good as food gets on this island.' where id = 'apple_pie';
update item_def set description = 'A cloth sack. Holds 40 things, and keeps a little of the weather off them if it is left out.' where id = 'sack';
update item_def set holds = 40 where id = 'sack';
update item_def set description = 'A stitched leather satchel with a flap. Holds 25 things, and what is in it rots at half the rate if you leave it lying about.' where id = 'satchel';
update item_def set holds = 25 where id = 'satchel';
update item_def set description = 'A deep leather pack on ribbon straps. Holds 60 things and sheds most of the weather. Drop a full one at a work post and it keeps.' where id = 'backpack';
update item_def set holds = 60 where id = 'backpack';
update item_def set description = 'A stake, a crossbar and a strip of metal for a marker. Driven into open ground off your deed, it stands half an hour to three hours by its quality, and one wildermon will work out of it as it would out of a settlement. When it goes over, the creature comes back to you.' where id = 'work_post';
update item_def set description = 'A stack of shallow boxes for a swarm to live in. Set it down on your deed and keep a Vesp there, and it fills itself with honey and beeswax. Holds 40 of them.' where id = 'hive';
update item_def set description = 'A grooved block the strands are laid round and twisted against. Nothing is roped without one.' where id = 'rope_tool';
update item_def set description = 'Spins wool, cotton and wemp into yarn. Stand at it to work.' where id = 'spindle';
update item_def set description = 'Weaves yarn into cloth. Stand at it to work.' where id = 'loom';
update item_def set description = 'A stone smelter, built flat-packed and bedded in where you set it down. Turns ore into lumps, and mixes alloys. It stands on your own deed.' where id = 'smelter';
update item_def set description = 'A brick kiln for firing clay. Set it down anywhere dry and flat; take it up again when it is cold and empty.' where id = 'kiln';
update item_def set description = 'A bread oven of brick and mortar. Feed it wood, light it, and cook at it as you would a fire — only it does not burn the dinner.' where id = 'oven';
update item_def set description = 'A lined shaft with a windlass over it. It draws its own water, faster the better it was sunk, and holds 50 litres.' where id = 'well';
update item_def set description = 'A deep bin for bulk: bricks, ore, planks, grain. Holds 400 things, and nothing that does not stack.' where id = 'bulk_bin';
update item_def set description = 'An open crate with a rotten bottom. Anything put in it rots thirty times faster than it would in the rain.' where id = 'trash_crate';
update item_def set description = 'Two wheels and a pair of shafts. Take hold of it and it follows you about, carrying 100 things you do not have to.' where id = 'cart';
update item_def set description = 'A two-wheeled cart with a box body and a seat over the axle. It holds 1000 things of any weight, and nothing under a hitched wildermon will move it.' where id = 'large_cart';
update item_def set description = 'Four wheels, two axles and a bed you could sleep a family on. It holds 10000 things of any weight, and it does not roll until all four yokes have a wildermon in them.' where id = 'wagon';
update item_def set description = 'A clinker hull with a pair of oars in her. Launch her into two deep of water, climb aboard and row. Carries 300 things and you.' where id = 'rowing_boat';
update item_def set description = 'A decked hull with a mast, a sail and a rudder. Four deep of water under her, and she goes where the coast goes. Carries 1500 things.' where id = 'sailing_boat';
update item_def set description = 'Holds 30 litres of one liquid, and nothing solid at all.' where id = 'small_barrel';
update item_def set description = 'Holds 250 litres of one liquid. It takes a while to fill and longer to empty.' where id = 'large_barrel';
