create or replace function fuel_value(p_item text) returns double precision language sql immutable as $fn$
  select case p_item
    when 'thatch' then 60
    when 'shaft' then 90
    when 'plank' then 120
    when 'peat' then 180
    when 'timber' then 240
    when 'log' then 600
    when 'coal' then 900
  end::double precision
$fn$;
